function longestSelfAdding(arr: number[]): number {
  const has = new Set(arr);
  let best = 0;
  for (let i = 0; i < arr.length; i++) {
    for (let j = i + 1; j < arr.length; j++) {
      let a = arr[i], b = arr[j], len = 2;
      while (has.has(a + b)) {
        [a, b] = [b, a + b];
        len++;
      }
      if (len > 2) best = Math.max(best, len);
    }
  }
  return best;
}

