function longestSelfAdding(arr: number[]): number {
  const n = arr.length;
  const index = new Map<number, number>();
  arr.forEach((v, i) => index.set(v, i));
  const len: number[][] = Array.from({ length: n }, () => new Array(n).fill(2));
  let best = 0;
  for (let k = 0; k < n; k++) {
    for (let j = 0; j < k; j++) {
      const prev = arr[k] - arr[j];
      if (prev >= arr[j]) continue; // the earlier term must be smaller than arr[j]
      const i = index.get(prev);
      if (i !== undefined) {
        len[j][k] = len[i][j] + 1;
        best = Math.max(best, len[j][k]);
      }
    }
  }
  return best;
}

